<?phpnamespace app\api\controller;use app\api\model\Goods as GoodsModel;use app\api\model\Category as CategoryModel;use app\api\model\Cart as CartModel;/** * 商品控制器 */class Goods extends Controller{    /**     * 商品列表 - 点餐接口     */    public function lists($order_mode,$table_id)    {        $model = new CategoryModel;        $category = $model->getList(false);        $model = new GoodsModel;        $result = $model->getGoodsList($category,$this->user_id,$order_mode,$table_id);        $category = $result['category'];        $order_total_num = $result['cartlist']['order_total_num'];        $order_total_price = $result['cartlist']['order_total_price'];        $min_price = $result['cartlist']['min_price'];        $goodslist = $result['cartlist']['goods_list'];        $order_pay_price = $result['cartlist']['order_pay_price'];        $pack_price = $result['cartlist']['pack_price'];        return $this->renderSuccess(compact('category','order_total_num','pack_price','order_pay_price','order_total_price','min_price','goodslist'));    }    /**     * 获取商品详情     */    public function detail($goods_id)    {        // 商品详情        $detail = GoodsModel::detail($goods_id);        if (!$detail || $detail['goods_status']['value'] != 10) {            return $this->renderError('很抱歉，商品信息不存在或已下架');        }        // 规格信息        if($detail['spec_type'] == 20){            $detail['specData'] = $detail->getManySpecData($detail['spec_rel'], $detail['spec']);        }else{            $detail['specData'] = null;        }        // 购物车商品数量                $detail = (new CartModel($this->user_id))->getGoodsNum($detail);        return $this->renderSuccess($detail/*compact('detail', 'total_num', 'specData')*/);    }}